WITH flattened_attrs AS (SELECT id, service, log_ts, latency_ms, SHIFTRIGHT(status_code, 2) AS status_code_high, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, context['trace'] AS trace FROM app_logs WHERE service = 'billing') SELECT CASE WHEN retry_count >= 4 THEN 'LARGE' ELSE 'SMALL' END AS retry_count_tier, AVG(status_code_high) AS avg_status_code_high, ROUND(AVG(retry_count), 2) AS avg_retry_count, COUNT(*) FILTER (WHERE service = 'auth') AS auth_rows, COUNT(*) AS row_count, MIN(log_ts) AS first_log_ts, GROUPING(CASE WHEN retry_count >= 4 THEN 'LARGE' ELSE 'SMALL' END) AS grouping_level FROM flattened_attrs GROUP BY CUBE (CASE WHEN retry_count >= 4 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY avg_status_code_high
